use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut sorted_data = Vec::new();
    for row in input.as_array() {
        let key = row[0].as_i64().unwrap();
        let value = row[1].as_i64().unwrap();
        sorted_data.push((key, value));
    }

    sorted_data.sort_unstable_by(|a, b| (a.0, a.1));
    sorted_data.into_iter().map(|(k, v)| serde_json::Value::from((k, v))).collect()
}

fn main() {
    let input = serde_json::Value::from("[[2,9],[1,4],[2,3]]");
    let expected = serde_json::Value::from("[[1,4],[2,3],[2,9]]");
    assert_eq!(solve(input), expected);
}
```

